 (async function () {
 const listEl = document.getElementById("recent-books-list");
 try {
 const response = await fetch("http://localhost:/api/bookshelf/list/");
 if (!response.ok) throw new Error("API failed");
 const books = await response.json();
 // Replace this with your rendering code, for now just show titles:
 listEl.innerHTML = books.map(book =>
 `<div>${book.title} <span style="color:;">${book.author || ''}</span></div>`
 ).join('');
 } catch (err) {
 listEl.innerHTML = `
 <div style="color:b;padding:em ;">
 <strong>Sorry, the book service is temporarily unavailable.</strong><br>
 <button id="books-retry-btn" style="margin-top:.em;padding:.em .em;border-radius:em;background:d;color:fff;border:none;cursor:pointer;">Retry</button>
 <div style="font-size:.em;color:;margin-top:.em;">(Check your network connection or try again in a few minutes.)</div>
 </div>
 `;
 document.getElementById("books-retry-btn").onclick = () => location.reload();
 console.error("Widget error:", err);
 }
 })();
</script>
