---

 ️ What This Widget Will Do

- Fetch your reading data from your REST API (e.g. `/api/books/`).
- Display each book (title, author, cover, or whatever you want).
- Configurable: easily set number of books, user name, etc.
- Self-contained: minimal dependencies (just React + fetch).

---

  Here’s a Drop-in React Widget Example

```jsx
import React, { useEffect, useState } from "react";

export default function WeReadWidget({
 api = "https://yourdomain.com/api/books/",
 title = "What I'm Reading",
 max = ,
 style = {},
}) {
 const [books, setBooks] = useState([]);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 fetch(api)
 .then((res) => res.json())
 .then((data) => {
 setBooks(data.slice(, max));
 setLoading(false);
 });
 }, [api, max]);

 return (
 <div
 style={{
 border: "px solid ddd",
 borderRadius: "px",
 padding: "em",
 maxWidth: "px",
 fontFamily: "sans-serif",
 background: "fafbfc",
 ...style,
 }}
 >
 <h style={{ margin: "  .em ", fontSize: ".em" }}>{title}</h>
 {loading ? (
 <div>Loading…</div>
 ) : (
 <ul style={{ padding: , margin: , listStyle: "none" }}>
 {books.map((book, idx) => (
 <li key={idx} style={{ margin: "  .em " }}>
 <strong>{book.title}</strong>
 <br />
 <span style={{ color: "", fontSize: ".em" }}>
 {book.author}
 </span>
 </li>
 ))}
 </ul>
 )}
 <div style={{ fontSize: ".em", color: "ccc", marginTop: "em" }}>
 Powered by WeRead
 </div>
 </div>
 );
}
```

