from django.views.decorators.csrf import csrf_exempt
from django.http import JsonResponse
import requests
import json

BOOKFUNNEL_API_KEY = 'YOUR_BOOKFUNNEL_API_KEY'
BOOK_ID = 'YOUR_BOOKFUNNEL_BOOK_ID'  Example: 'BFxxxxxxxxxx'
BOOKFUNNEL_API_URL = 'https://api.bookfunnel.com/v/create_book_link'

@csrf_exempt  For simple demo; in production, set up proper CSRF token handling!
def get_book_link(request):
 if request.method != 'POST':
 return JsonResponse({'message': 'Invalid method.'}, status=)

 try:
 data = json.loads(request.body)
 email = data.get('email', '').strip()
 except Exception:
 return JsonResponse({'message': 'Invalid JSON.'}, status=)

 if not email:
 return JsonResponse({'message': 'Email is required.'}, status=)

 resp = requests.post(
 BOOKFUNNEL_API_URL,
 headers={'X-BookFunnel-APIKey': BOOKFUNNEL_API_KEY},
 data={'object': BOOK_ID, 'email': email}
 )

 if resp.status_code == :
 res = resp.json()
 if res.get('link'):
 return JsonResponse({'link': res['link']})
 else:
 return JsonResponse({'message': res.get('message', 'No link returned.')})
 else:
 return JsonResponse({'message': 'Error connecting to BookFunnel.'}, status=)
```

