- Make it easy to load more posts via “Load More” or infinite scroll

---

  . Paginated Feed Endpoint (Backend)

In `writer_app.py`, replace or add this endpoint:

```python
@app.route('/api/posts')
def api_posts():
 page = request.args.get('page', default=, type=int)
 per_page = request.args.get('per_page', default=, type=int)
 category = request.args.get('category', default=None, type=str)

 query = Post.query.order_by(Post.timestamp.desc())

 if category and category.lower() != 'all':
 query = query.filter_by(category=category)

 pagination = query.paginate(page=page, per_page=per_page, error_out=False)
 posts = pagination.items

 return jsonify({
 'posts': [
 {
 'title': p.title,
 'category': p.category,
 'body': p.body,
 'timestamp': p.timestamp.isoformat()
 } for p in posts
 ],
 'has_next': pagination.has_next,
 'page': page
 })
```

---

  . Viewer Frontend Update (JavaScript)

In your viewer HTML, replace or update your `<script>` block:

```javascript
let currentPage = ;
let hasNextPage = true;
let selectedCategory = "All";

function renderPost(post) {
 const div = document.createElement('div');
 div.className = 'post';
 div.innerHTML = `<h>${post.title}</h>
 <small><strong>${post.category}</strong> • ${new Date(post.timestamp).toLocaleString()}</small>
 <p>${post.body.replace(/\\n/g, '<br>')}</p>`;
 return div;
}

async function loadPosts(reset = false) {
 if (reset) {
 currentPage = ;
 document.getElementById('postsContainer').innerHTML = '';
 }

 const res = await fetch(`/api/posts?page=${currentPage}&per_page=&category=${selectedCategory}`);
 const data = await res.json();

 data.posts.forEach(p => {
 document.getElementById('postsContainer').appendChild(renderPost(p));
 });

 hasNextPage = data.has_next;
 document.getElementById('loadMore').style.display = hasNextPage ? 'block' : 'none';
}

document.getElementById('categoryFilter').onchange = (e) => {
 selectedCategory = e.target.value;
 loadPosts(true);
};

document.getElementById('loadMore').onclick = () => {
 if (hasNextPage) {
 currentPage++;
 loadPosts();
 }
};
```

